/**
 * AGENDABOT — RESUMEN DIARIO (FASE 7)
 * Nodo: Code — Modo: "Run Once for All Items"
 * Se ejecuta después de dos nodos Google Sheets:
 *   "Get Citas Hoy"  (CITAS filtrado por fecha = hoy)
 *   "Get Tareas Hoy" (TAREAS filtrado por fecha_objetivo = hoy)
 * y antes de "Get Usuarios Activos" (USUARIOS filtrado por permitido = TRUE),
 * que se usa para saber a quién enviarle el resumen.
 *
 * Salida: un item POR CADA usuario a notificar, con chat_id y el texto armado,
 * listo para conectarse directo a un nodo Telegram "Send Message" con
 * Chat ID = {{$json.chat_id}}.
 *
 * NOTA (fix): si "Get Usuarios Activos" no encuentra ningún usuario activo
 * (0 filas), este nodo simplemente no genera items y "Enviar Resumen" no se
 * ejecuta — esto es esperado (no hay a quién enviarle nada), no un error.
 * Si el problema es que SIEMPRE da 0 usuarios cuando debería haber al menos
 * uno, revisa el valor real de la columna "permitido" en USUARIOS (ver
 * retroalimentación).
 */

function hoyISO() {
  return new Date().toISOString().slice(0, 10);
}

const citasHoy = $('Get Citas Hoy').all();
const tareasHoy = $('Get Tareas Hoy').all();
const usuarios = $('Get Usuarios Activos').all();

let cuerpo = `☀️ *Resumen del día — ${hoyISO()}*\n\n`;

if (citasHoy.length === 0) {
  cuerpo += '📅 No tienes citas hoy.\n\n';
} else {
  cuerpo += '📅 *Citas de hoy:*\n';
  cuerpo += citasHoy
    .sort((a, b) => String(a.json.hora).localeCompare(String(b.json.hora)))
    .map(c => `• ${c.json.hora} — ${c.json.nombre} (${c.json.motivo})`)
    .join('\n');
  cuerpo += '\n\n';
}

if (tareasHoy.length === 0) {
  cuerpo += '✅ No tienes tareas con fecha objetivo hoy.';
} else {
  cuerpo += '✅ *Tareas con vencimiento hoy:*\n';
  cuerpo += tareasHoy
    .filter(t => String(t.json.estado).toUpperCase() !== 'COMPLETADA')
    .map(t => `• [${t.json.prioridad}] ${t.json.titulo}`)
    .join('\n');
}

// Filtramos aquí (en código) en vez de en el nodo Google Sheets, porque el
// filtro de Sheets compara texto exacto y falla si "permitido" es un
// checkbox (booleano true/false) en vez de texto "TRUE". Aceptamos ambos
// formatos, y de paso descartamos cualquier fila sin telegram_user (incluye
// el item vacío "fantasma" que Google Sheets puede emitir cuando
// alwaysOutputData está activo y no hay filas), evitando el error de
// Telegram "chat_id is empty".
function esPermitido(valor) {
  if (valor === true) return true;
  return String(valor).trim().toUpperCase() === 'TRUE';
}

const usuariosActivos = usuarios.filter(
  u => u.json && esPermitido(u.json.permitido) && u.json.telegram_user
);

// Un item por usuario activo, para que el nodo Telegram "Send Message" itere
// automáticamente y le envíe el resumen a cada uno.
return usuariosActivos.map(u => ({
  json: {
    chat_id: u.json.telegram_user,
    resumen_texto: cuerpo,
  },
}));
